var CalendarEvents=(()=>{
function date(s){if(typeof s!=='string'||!/^20\d{2}-\d{2}-\d{2}$/.test(s))return '';const d=new Date(s+'T00:00:00Z');return Number.isFinite(d.getTime())&&d.toISOString().slice(0,10)===s?s:''}
function time(s){return /^([01]\d|2[0-3]):[0-5]\d$/.test(s||'')?s:''}
function build(storage,{includeNotes=true}={}){const read=(k,f)=>{try{return JSON.parse(storage.getItem(k))||f}catch{return f}},state=read('immobrain-listing-status-v1',{}),views=read('immobrain-viewings-v1',[]),timeline=read('immobrain-viewing-timeline-v1',{}),objects=new Map(),aliases=new Map(),out=[];const note=(...parts)=>includeNotes?[...new Set(parts.filter(v=>typeof v==='string'&&v.trim()).map(v=>v.trim()))].join('\n\n').slice(0,10000):'';for(const [key,v]of Object.entries(state)){const x=v?.snapshot||{},a={...x,...v?.address},item={id:'object:'+key,key,title:x.title||'Immobilie',location:[a.street,a.zipcode,a.city].filter(Boolean).join(', '),note:v?.note?.text||'',dates:new Set()};objects.set(item.id,item);aliases.set(key,item.id);for(const p of x.portalListings||[])aliases.set(p.local_key||JSON.stringify([String(p.source??''),String(p.immo_id??'')]),item.id)}
for(const v of Array.isArray(views)?views:[]){if(!v?.id)continue;const f=v.data?.fields||{},id=f.listingRef?(aliases.get(f.listingRef)||'object:'+f.listingRef):'viewing:'+v.id;let item=objects.get(id);if(!item){item={id,key:f.listingRef,title:v.name||f.address||'Immobilie',location:f.address||'',note:'',dates:new Set()};objects.set(id,item)}const d=date(f.date);if(d){item.dates.add(d);out.push({id:'visit:'+v.id,date:d,time:time(f.time),duration:Number(f.duration)||60,title:'Besichtigung · '+item.title,location:item.location,note:note(item.note,timeline[id]?.note,...Object.values(v.data?.notes||{})),path:'/besichtigung.html?viewing='+encodeURIComponent(v.id)})}}
for(const [id,r]of Object.entries(timeline)){if(!r||typeof r!=='object')continue;const x=objects.get(id);if(!x)continue;const path='/besichtigungskalender.html#obj-'+encodeURIComponent(id),add=(kind,d,title,t='',duration=60)=>{if(date(d))out.push({id:kind+':'+id,date:d,time:time(t),duration:Number(duration)||60,title:title+' · '+x.title,location:x.location,note:note(x.note,r.note),path})};if(date(r.visit)&&!x.dates.has(r.visit))add('manual-visit',r.visit,'Besichtigung',r.visitTime,r.visitDuration);if(r.decision==='no')continue;add('offer',r.offer,'Angebot gestellt');for(let n=1;n<=4;n++)add('follow'+n,r['follow'+n],n+'. Nachfassen');add('next',r.next,'Nachfassen geplant',r.nextTime,r.nextDuration||15)}
return out.map(e=>({...e,title:e.title.slice(0,400),location:e.location.slice(0,300)})).sort((a,b)=>a.id.localeCompare(b.id))}
return {build};})();
